WITH "m0" AS ( SELECT "s" AS "t0" , "s"."ctid" AS "k0" FROM "public"."mutation_item" AS "s" WHERE false ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ) SELECT json_build_object( 'affected_rows' , (SELECT count(*) FROM "r0" ) , 'returning' , (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) ), '[]') FROM "r0" AS "t0" ) )
WITH "m0" AS ( UPDATE "public"."mutation_item" AS "s" SET "title" = $1 , "note" = $2 WHERE ( true AND ( "s"."id" = $3 ) AND ( "s"."owner_id" = $4 ) ) RETURNING "s" AS "t0" , NULL::tid AS "k0" , CAST(CASE WHEN "s"."score" >= $5 THEN '1' ELSE 'rusuna: permission check failed' || left( "s"."ctid" ::text, 0) END AS integer) AS "check__constraint" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ) SELECT json_build_object( 'affected_rows' , (SELECT count(*) FROM "r0" ) , 'returning' , (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) ), '[]') FROM "r0" AS "t0" ) )
